from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove any spaces from the input string
    result = []  # Step 2: Initialize an empty list to store the extracted groups

    stack = []
    start = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                start = stack.pop()
                result.append(paren_string[start:i+1])  # Step 3 & 4: Identify and extract individual balanced parenthesis groups

    return result  # Step 5: Return the list of extracted groups

# Test the function
print(separate_paren_groups('( ) (( )) (( )( ))'))  # Output: ['()', '(())', '(()())']

